import openpyxl


class ExcelProcessor:
    DEFAULT_FILE_SUFFIX = '_process.xlsx'
    ROW_SEPARATOR = '.'

    def __init__(self):
        pass

    def read_excel(self, file_name):
        data = []
        try:
            workbook = openpyxl.load_workbook(file_name)
            sheet = workbook.active
            for row in sheet.iter_rows(values_only=True):
                data.append(row)
            workbook.close()
            return data
        except Exception:
            return None

    def write_excel(self, data, file_name):
        try:
            workbook = openpyxl.Workbook()
            sheet = workbook.active
            for row in data:
                sheet.append(row)
            workbook.save(file_name)
            workbook.close()
            return 1
        except Exception:
            return 0

    def validate_data(self, data, N):
        """
        Validates that data is not None and N is within bounds of the first row.
        """
        return data is not None and N < len(data[0])

    def process_row(self, row, N):
        """
        Processes a single row by appending a transformed value based on the Nth column.
        """
        new_row = list(row[:])
        value = row[N]
        if not str(value).isdigit():
            new_row.append(str(value).upper())
        else:
            new_row.append(value)
        return new_row

    def generate_process_file_name(self, save_file_name):
        """
        Generates the new file name by appending the process suffix to the original file name.
        """
        base_name = save_file_name.split(self.ROW_SEPARATOR)[0]
        return base_name + self.DEFAULT_FILE_SUFFIX

    def process_excel_data(self, N, save_file_name):
        data = self.read_excel(save_file_name)
        if not self.validate_data(data, N):
            return 0, self.generate_process_file_name(save_file_name)

        new_data = []
        for row in data:
            new_row = self.process_row(row, N)
            new_data.append(new_row)

        new_file_name = self.generate_process_file_name(save_file_name)
        success = self.write_excel(new_data, new_file_name)
        return success, new_file_name
